function render(page){const meta=PAGE_META[page],content=$('#content');if(!meta||!content)return false;$$('#sidebar-nav .nav-item').forEach(x=>x.classList.toggle('active',x.dataset.growthPage===page));$('#page-eyebrow').textContent=meta[0];$('#page-title').textContent=meta[1];$('#page-subtitle').textContent=meta[2];$('#breadcrumb').textContent=`${meta[0]} / ${meta[1]}`;content.innerHTML=`<div class="notice-banner"><b>CSV-first workspace.</b> Amazon API remains disabled; all metrics below come from imported or already-loaded data.</div><div class="top-gap">${RENDERERS[page]()}</div>`;bind(content);root.KeywordOSI18N?.apply(document);history.replaceState(null,'',`#page=${encodeURIComponent(page)}`);return true}
function bind(rootNode){$$('[data-growth-import]',rootNode).forEach(b=>b.addEventListener('click',()=>openImport(b.dataset.growthImport)));$$('[data-growth-template]',rootNode).forEach(b=>b.addEventListener('click',()=>downloadTemplate(b.dataset.growthTemplate)));$$('[data-growth-page]',rootNode).forEach(b=>b.addEventListener('click',()=>render(b.dataset.growthPage)));$$('[data-growth-listing]',rootNode).forEach(el=>el.addEventListener('input',()=>{const current=load('listing')[0]||{};current[el.dataset.growthListing]=el.value;save('listing',[current]);clearTimeout(el._timer);el._timer=setTimeout(()=>render('listing-optimizer'),250)}))}
