function captureBaseline(action){if(!action||load('action-outcomes').some(x=>x.id===action.id))return;const matching=adsRows().filter(r=>r.searchTerm===action.term||r.target===action.term||r.campaign===action.scope),dates=[...new Set(matching.map(r=>r.date).filter(Boolean))].sort(),windowDays=Math.min(14,dates.length),windowDates=new Set(dates.slice(-windowDays)),windowRows=matching.filter(r=>windowDates.has(r.date)),dateMax=dates.at(-1)||'',dateMin=dates.at(-windowDays)||'';save('action-outcomes',[...load('action-outcomes'),{id:action.id,approvedAt:action.approvedAt||'',dateMin,dateMax,windowDays,metrics:{...metricRows(windowRows),dateMin,dateMax}}],'Approved action baseline')}
